/* SOURCE: src/kernel/protection.css */
/* 功能/状态保护；不保存主题构图。 */
#top-settings-holder .drawer-toggle::after,
#send_form::before,
#send_form::after {
    pointer-events: none;
}

#top-settings-holder :is(.drawer-toggle, .drawer-icon):focus-visible,
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate):focus-visible,
#chat :is(.mes_button, .menu_button, .swipe_left, .swipe_right):focus-visible {
    outline: 1px solid var(--rr-red-bright);
    outline-offset: 3px;
    box-shadow: none;
}

@media (prefers-reduced-motion: reduce) {
    #top-settings-holder *,
    #send_form *,
    #chat * {
        scroll-behavior: auto;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
    }
}

/* SOURCE: src/tokens.css */
/* Author: @jiuyi0204 | 未经许可禁止二改、二传、转载或重新打包。 */
@font-face {
    font-family: "Noto Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notoserifsc/notoserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 200 900;
    font-display: swap;
}

@font-face {
    font-family: "LXGW Marker Gothic";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/lxgwmarkergothic/lxgwmarkergothic.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --rr-ink: #050506;
    --rr-ink-soft: #0d0d0f;
    --rr-panel: rgba(7, 7, 8, 0.97);
    --rr-panel-soft: rgba(17, 16, 18, 0.94);
    --rr-paper: #e8e3d8;
    --rr-paper-soft: #cfc8bd;
    --rr-muted: #9e9790;
    --rr-disabled: #746d69;
    --rr-red: #a91517;
    --rr-red-bright: #ce3435;
    --rr-red-deep: #651012;
    --rr-line: rgba(232, 227, 216, 0.24);
    --rr-line-strong: rgba(232, 227, 216, 0.5);
    --rr-red-wash: rgba(169, 21, 23, 0.17);
    --rr-shadow: 0 18px 48px rgba(0, 0, 0, 0.44);
    --rr-focus: 0 0 0 2px var(--rr-ink), 0 0 0 3px var(--rr-red-bright);
    --rr-radius-sm: 2px;
    --rr-radius-md: 6px;
    --rr-radius-lg: 12px;
    --rr-space-1: 0.32rem;
    --rr-space-2: 0.58rem;
    --rr-space-3: 0.9rem;
    --rr-space-4: 1.3rem;
    --rr-space-5: 1.9rem;
    --rr-speed: 150ms;
    --rr-font-body: "Noto Serif SC", "Songti SC", "SimSun", serif;
    --rr-font-display: "LXGW Marker Gothic", "Noto Serif SC", serif;
    --rr-bg-desktop: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/f1f4526e6399e8bd2b294341e8c0a2ae92c8b689/assets/%E8%B5%A4%E8%8A%A6%E5%A4%9C%E8%A1%8C/background-desktop.png");
    --rr-bg-mobile: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/f1f4526e6399e8bd2b294341e8c0a2ae92c8b689/assets/%E8%B5%A4%E8%8A%A6%E5%A4%9C%E8%A1%8C/background-mobile.png");

    --st-theme-bg: var(--rr-ink);
    --st-theme-surface: var(--rr-panel-soft);
    --st-theme-surface-soft: var(--rr-panel-soft);
    --st-theme-text: var(--rr-paper);
    --st-theme-muted: var(--rr-muted);
    --st-theme-disabled: var(--rr-disabled);
    --st-theme-accent: var(--rr-red);
    --st-theme-border: var(--rr-line);
    --st-theme-font-body: var(--rr-font-body);
    --st-theme-font-emphasis: var(--rr-font-body);
    --st-theme-font-display: var(--rr-font-display);
    --st-theme-weight-body: 400;
    --st-theme-weight-emphasis: 650;
    --st-theme-weight-display: 400;
    --st-theme-font-size-body: 0.98em;
    --st-theme-font-size-user: 0.96em;
    --st-theme-font-size-character: 1em;
    --st-theme-font-size-meta: 0.82em;
    --st-theme-font-size-input: 1em;
}

/* SOURCE: src/windows/background.css */
html,
#bg1,
#bg_custom {
    background-color: var(--rr-ink) !important;
}

/* 官方 #bg1 位于 z-index:-1；body 必须透明，否则纯黑 body 会遮住底图。 */
body {
    background-color: transparent !important;
}

#bg1,
#bg_custom {
    background-image: var(--rr-bg-desktop) !important;
    background-position: center bottom !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    filter: none !important;
    opacity: 1 !important;
    visibility: visible !important;
}

/* SOURCE: src/chat-layout.css */
/* L16 满幅插画叠文的无头像连续阅读变体。 */
#chat {
    color: var(--rr-paper);
    background: linear-gradient(90deg, rgba(5, 5, 6, 0.46), rgba(5, 5, 6, 0.14) 50%, rgba(5, 5, 6, 0.46));
    scrollbar-color: var(--rr-red-deep) rgba(5, 5, 6, 0.38);
}

#chat .mesAvatarWrapper {
    display: none !important;
}

#chat .mes {
    box-sizing: border-box;
    width: 100%;
    padding: var(--rr-space-4) clamp(var(--rr-space-3), 3.6vw, 3.2rem);
    border: 0;
    background: transparent;
    color: var(--rr-paper);
}

#chat .mes + .mes {
    border-top: 1px solid rgba(232, 227, 216, 0.08);
}

#chat .mes_block {
    flex: 1 1 auto;
    min-width: 0;
    width: 100%;
    box-sizing: border-box;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
    max-width: 62ch;
    margin-inline: auto;
    padding: clamp(1.05rem, 2.3vw, 2rem) clamp(1rem, 3vw, 2.5rem);
    background: rgba(5, 5, 6, 0.64);
    border-inline-start: 1px solid var(--rr-line);
    border-inline-end: 1px solid rgba(232, 227, 216, 0.08);
}

#chat .mes[is_user="true"] .mes_block {
    max-width: min(34rem, 78%);
    margin-inline-start: auto;
    padding: 0.85rem 1.15rem 0.95rem;
    background: linear-gradient(105deg, rgba(101, 16, 18, 0.92), rgba(169, 21, 23, 0.78));
    border-inline-end: 4px solid var(--rr-paper-soft);
    border-radius: var(--rr-radius-sm) var(--rr-radius-lg) var(--rr-radius-sm) var(--rr-radius-md);
    color: #fff9ee;
}

#chat .mes[is_system="true"] .mes_block,
#chat .smallSysMes {
    max-width: 52ch;
    margin-inline: auto;
    padding: 0.72rem 1rem;
    background: rgba(7, 7, 8, 0.9);
    border-block: 1px solid var(--rr-line);
    color: var(--rr-paper-soft);
}

#chat .ch_name {
    min-width: 0;
    margin-bottom: var(--rr-space-3);
    gap: var(--rr-space-2);
    border-bottom: 1px solid rgba(232, 227, 216, 0.11);
    padding-bottom: var(--rr-space-2);
}

#chat .name_text {
    color: var(--rr-red-bright);
    font-family: var(--rr-font-display);
    font-weight: 400;
    letter-spacing: 0.09em;
}

#chat .mes[is_user="true"] .name_text {
    color: #fff7ea;
}

#chat .timestamp,
#chat .mesIDDisplay,
#chat .mes_timer,
#chat .tokenCounterDisplay,
#chat .swipes-counter {
    color: var(--rr-muted);
    font-family: var(--rr-font-body);
    font-size: var(--st-theme-font-size-meta);
    text-shadow: none;
}

#chat .mes[is_user="true"] .timestamp {
    color: rgba(255, 249, 238, 0.72);
}

#chat .mes_buttons,
#chat .mes_edit_buttons,
#chat .mes_reasoning_actions {
    color: var(--rr-muted);
    filter: none;
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button, .swipe_left, .swipe_right):is(:hover, :focus-visible),
#chat .mes_buttons:focus-within {
    color: var(--rr-red-bright);
    text-shadow: none;
    filter: none;
}

#chat .swipe_left,
#chat .swipeRightBlock {
    color: var(--rr-paper-soft);
    text-shadow: none;
    filter: none;
}

#chat .mes.last_mes {
    padding-bottom: calc(var(--rr-space-5) + 0.5rem);
}

/* SOURCE: src/full-text.css */
/* T03 诗性留白，只处理真实正文语义节点。 */
#chat .mes_text {
    max-width: 100%;
    color: var(--rr-paper);
    font-family: var(--rr-font-body);
    font-size: var(--st-theme-font-size-body);
    font-weight: 400;
    line-height: 1.82;
    letter-spacing: 0.018em;
    overflow-wrap: anywhere;
    text-shadow: none;
}

#chat .mes[is_user="true"] .mes_text {
    color: #fff9ee;
    font-size: var(--st-theme-font-size-user);
    line-height: 1.62;
    letter-spacing: 0.035em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    font-size: var(--st-theme-font-size-character);
}

#chat .mes[is_user="false"][is_system="false"] .mes_text p + p {
    margin-top: 1.15em;
    text-indent: 2em;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    margin: 1.45em 0 0.65em;
    color: var(--rr-paper);
    font-family: var(--rr-font-display);
    font-weight: 400;
    letter-spacing: 0.08em;
    line-height: 1.35;
}

#chat .mes_text :is(strong, b) {
    color: #fff8ec;
    font-family: var(--rr-font-body);
    font-weight: 650;
}

#chat .mes_text :is(em, i) {
    color: #d7aaa4;
}

#chat .mes_text a {
    color: var(--rr-red-bright);
    text-decoration-color: rgba(206, 52, 53, 0.55);
    text-underline-offset: 0.18em;
}

#chat .mes_text blockquote {
    margin: 1.2em 0;
    padding: 0.4em 0 0.4em 1.15em;
    border-inline-start: 3px solid var(--rr-red);
    color: var(--rr-paper-soft);
    background: rgba(169, 21, 23, 0.08);
}

#chat .mes_text :is(ul, ol) {
    padding-inline-start: 1.5em;
}

#chat .mes_text li::marker {
    color: var(--rr-red-bright);
}

#chat .mes_text hr {
    height: 1px;
    margin: 1.8em auto;
    border: 0;
    background: linear-gradient(90deg, transparent, var(--rr-red), transparent);
}

#chat .mes_text :is(code, pre) {
    font-family: "Courier Prime", "Cascadia Mono", Consolas, monospace;
}

#chat .mes_text code {
    padding: 0.08em 0.3em;
    border: 1px solid rgba(206, 52, 53, 0.28);
    background: rgba(0, 0, 0, 0.6);
    color: #f1d9d3;
}

#chat .mes_text pre {
    max-width: 100%;
    overflow-x: auto;
    padding: 1em;
    border: 1px solid var(--rr-line);
    background: #080809;
    color: var(--rr-paper);
    white-space: pre;
}

#chat .mes_text pre code {
    padding: 0;
    border: 0;
    background: transparent;
}

#chat .mes_text table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
}

#chat .mes_text :is(th, td) {
    border-color: var(--rr-line);
    background: rgba(5, 5, 6, 0.72);
}

#chat .mes_text th {
    color: var(--rr-red-bright);
    font-family: var(--rr-font-display);
    font-weight: 400;
}

#chat .mes_text img,
#chat .mes_media_wrapper img {
    max-width: 100%;
    height: auto;
    border: 1px solid var(--rr-line);
}

#chat .mes_reasoning_details {
    margin: 0 0 1.1em;
    border: 1px solid rgba(169, 21, 23, 0.48);
    border-radius: var(--rr-radius-md);
    background: rgba(9, 8, 9, 0.94);
    color: var(--rr-paper-soft);
    box-shadow: none;
}

#chat .mes_reasoning_summary {
    padding: 0.65em 0.8em;
    color: var(--rr-paper-soft);
    background: linear-gradient(90deg, var(--rr-red-wash), transparent 70%);
    border-bottom: 1px solid transparent;
}

#chat .mes_reasoning_details[open] .mes_reasoning_summary {
    border-bottom-color: var(--rr-line);
}

#chat .mes_reasoning_header_title {
    color: var(--rr-red-bright);
    font-family: var(--rr-font-display);
    letter-spacing: 0.06em;
    text-shadow: none;
}

#chat .mes_reasoning {
    padding: 0.9em 1em 1.05em;
    color: var(--rr-paper-soft);
    line-height: 1.7;
}

#chat .mes_reasoning_details :focus-visible {
    outline: 1px solid var(--rr-red-bright);
    outline-offset: 2px;
}

/* SOURCE: src/windows/topbar.css */
#top-bar,
#top-settings-holder {
    color: var(--rr-paper-soft);
    background: rgba(5, 5, 6, 0.96);
    border-bottom: 1px solid var(--rr-line);
    box-shadow: none;
    backdrop-filter: none;
}

#top-settings-holder > .drawer > .drawer-toggle {
    position: relative;
    color: var(--rr-paper-soft);
    background: transparent;
    border: 0;
    box-shadow: none;
}

/* 九入口保留原图标和点击区，只增加各不相同的赤色符号小物。 */
#top-settings-holder > .drawer > .drawer-toggle::before {
    position: absolute;
    inset: 0.04em 0.08em auto auto;
    z-index: 1;
    color: var(--rr-red-bright);
    font-family: var(--rr-font-display);
    font-size: 0.32em;
    line-height: 1;
    opacity: 0.78;
    pointer-events: none;
}

#ai-config-button > .drawer-toggle::before { content: "◇"; }
#sys-settings-button > .drawer-toggle::before { content: "⊹"; }
#advanced-formatting-button > .drawer-toggle::before { content: "✦"; }
#WI-SP-button > .drawer-toggle::before { content: "▤"; }
#user-settings-button > .drawer-toggle::before { content: "●"; }
#backgrounds-button > .drawer-toggle::before { content: "⌁"; }
#extensions-settings-button > .drawer-toggle::before { content: "■"; }
#persona-management-button > .drawer-toggle::before { content: "○"; }
#rightNavHolder > .drawer-toggle::before { content: "▥"; }

#top-settings-holder > .drawer > .drawer-toggle::after {
    content: "";
    position: absolute;
    inset: auto 24% 0;
    height: 1px;
    background: transparent;
    transition: background-color var(--rr-speed) ease, inset var(--rr-speed) ease;
}

#top-settings-holder .drawer-icon {
    color: var(--rr-paper-soft);
    text-shadow: none;
    filter: none;
    opacity: 0.86;
    transition: color var(--rr-speed) ease, opacity var(--rr-speed) ease, transform var(--rr-speed) ease;
}

#top-settings-holder > .drawer > .drawer-toggle:hover::after,
#top-settings-holder > .drawer > .drawer-toggle:focus-within::after {
    inset-inline: 8%;
    background: var(--rr-red-bright);
}

#top-settings-holder .drawer-toggle:hover .drawer-icon,
#top-settings-holder .drawer-toggle:focus-within .drawer-icon,
#top-settings-holder .drawer-icon.openIcon {
    color: var(--rr-red-bright);
    opacity: 1;
    transform: translateY(-1px);
}

/* 不修改 .drawer/.drawer-content 的宽度、定位、flex 或 inset。 */

/* SOURCE: src/windows/input.css */
#send_form {
    min-height: var(--bottomFormBlockSize);
    color: var(--rr-paper);
    background: rgba(5, 5, 6, 0.98);
    border: 1px solid var(--rr-line-strong);
    border-inline-color: rgba(169, 21, 23, 0.62);
    border-radius: var(--rr-radius-md);
    box-shadow: 0 -10px 32px rgba(0, 0, 0, 0.3);
    backdrop-filter: none;
}

#send_form:has(#send_textarea:focus-visible) {
    border-color: var(--rr-red-bright);
    box-shadow: 0 0 0 1px rgba(206, 52, 53, 0.26);
}

#send_textarea {
    min-width: 0;
    color: var(--rr-paper);
    background: transparent;
    border: 0;
    border-radius: 0;
    font-family: var(--rr-font-body);
    font-size: var(--st-theme-font-size-input);
    line-height: 1.5;
    box-shadow: none;
    text-shadow: none;
}

#send_textarea::placeholder {
    color: var(--rr-muted);
    opacity: 1;
}

#send_textarea:focus-visible {
    outline: 0;
}

#leftSendForm,
#rightSendForm {
    flex: 0 0 auto;
    color: var(--rr-paper-soft);
}

#send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, .stscript_btn) {
    position: relative;
    color: var(--rr-paper-soft);
    text-shadow: none;
    filter: none;
    background: transparent;
    border: 0;
    border-radius: 0;
    transition: color var(--rr-speed) ease, transform var(--rr-speed) ease;
}

#send_form :is(#options_button, #extensionsMenuButton)::after {
    position: absolute;
    inset: 0.12em 0.05em auto auto;
    color: var(--rr-red-bright);
    font-family: var(--rr-font-display);
    font-size: 0.34em;
    line-height: 1;
    pointer-events: none;
}

#send_form #options_button::after { content: "◇"; }
#send_form #extensionsMenuButton::after { content: "✦"; }

#send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, .stscript_btn):is(:hover, :focus-visible) {
    color: var(--rr-red-bright);
    transform: translateY(-1px);
}

#send_form :is(#send_but, #mes_stop) {
    inline-size: var(--bottomFormIconSize);
    block-size: var(--bottomFormIconSize);
    flex: 0 0 var(--bottomFormIconSize);
    color: #fff8ec;
    background: radial-gradient(circle at 42% 36%, var(--rr-red-bright), var(--rr-red-deep) 72%);
    border: 1px solid rgba(232, 227, 216, 0.46);
    border-radius: 50%;
    box-shadow: none;
    text-shadow: none;
    filter: none;
}


#send_form :is(#send_but, #mes_stop):is(:hover, :focus-visible) {
    color: #fff;
    border-color: var(--rr-paper);
    box-shadow: none;
}

#send_form.no-connection {
    border-color: rgba(116, 109, 105, 0.72);
}

#send_form.no-connection #send_textarea::placeholder {
    color: var(--rr-disabled);
}

#form_sheld.isExecutingCommandsFromChatInput #send_form,
#form_sheld.script_paused #send_form {
    border-color: var(--rr-red);
}

