        #rm_extensions_block,
        #PersonaManagement,
        #right-nav-panel
    ) {
        color: var(--rr-paper);
        background: #080809;
        box-shadow: none;
    }

    #completion_prompt_manager #completion_prompt_manager_list li {
        grid-template-columns: minmax(0, 1fr) 4.6rem 2.8rem;
    }

